7	+"use server";
8	+
9	+import { z } from "zod";
10	+import { revalidatePath } from "next/cache";
11	+import { requireRole } from "@/lib/auth";
12	+import { createClient } from "@/lib/supabase/server";
13	+import { getPayments } from "@/lib/integrations/payments";
14	+import { cancellationOutcome } from "@/lib/pricing";
15	+
16	+const uuid = z.string().uuid();
17	+
18	+/** Save a listener to the customer's favorites (idempotent). */
19	+export async function addFavorite(
20	+  providerId: string,
21	+): Promise<{ ok: boolean }> {
22	+  const profile = await requireRole("customer");
23	+  if (!uuid.safeParse(providerId).success) return { ok: false };
24	+  const supabase = await createClient();
25	+  const { error } = await supabase
26	+    .from("favorites")
27	+    .upsert(
28	+      { customer_id: profile.id, provider_id: providerId },
29	+      { onConflict: "customer_id,provider_id", ignoreDuplicates: true },
30	+    );
31	+  if (error) return { ok: false };
32	+  revalidatePath("/account");
33	+  return { ok: true };
34	+}
35	+
36	+/** Remove a listener from the customer's favorites. */
37	+export async function removeFavorite(
38	+  providerId: string,
39	+): Promise<{ ok: boolean }> {
40	+  const profile = await requireRole("customer");
41	+  const supabase = await createClient();
42	+  const { error } = await supabase
43	+    .from("favorites")
44	+    .delete()
45	+    .eq("customer_id", profile.id)
46	+    .eq("provider_id", providerId);
47	+  if (error) return { ok: false };
48	+  revalidatePath("/account");
49	+  return { ok: true };
50	+}
51	+
52	+export interface CancelResult {
53	+  ok: boolean;
54	+  released?: boolean;
55	+  error?: string;
56	+}
57	+
58	+/**
59	+ * Cancel a confirmed booking. Cancellation policy (SPEC §5): a scheduled session
60	+ * cancelled ≥1h before its start releases the hold, otherwise the block is
61	+ * charged. A "now" booking that was never joined releases (the customer never
62	+ * talked — "you're in control, leave any time"). Capture/refund go through the
63	+ * payments adapter.
64	+ */
65	+export async function cancelBooking(bookingId: string): Promise<CancelResult> {
66	+  const profile = await requireRole("customer");
67	+  const supabase = await createClient();
68	+
69	+  const { data: booking } = await supabase
70	+    .from("bookings")
71	+    .select("*")
72	+    .eq("id", bookingId)
73	+    .maybeSingle();
74	+  if (!booking || booking.customer_id !== profile.id) {
75	+    return { ok: false, error: "Booking not found." };
76	+  }
77	+  if (booking.status !== "confirmed") {
78	+    return { ok: false, error: "This booking can't be cancelled." };
79	+  }
80	+
81	+  let release: boolean;
82	+  if (booking.start_mode === "scheduled") {
83	+    release =
84	+      cancellationOutcome({
85	+        priceBlockCents: booking.price_block_cents,
86	+        scheduledAt: booking.scheduled_at,
87	+        nowMs: Date.now(),
88	+      }).action === "release";
89	+  } else {
90	+    release = true; // a "now" booking that was never joined
91	+  }
92	+
93	+  const payments = getPayments();
94	+  if (booking.payment_ref) {
95	+    if (release) {
96	+      await payments.refund({
97	+        paymentRef: booking.payment_ref,
98	+        amountCents: booking.price_block_cents,
99	+      });
100	+    } else {
101	+      await payments.capture({
102	+        paymentRef: booking.payment_ref,
103	+        amountCents: booking.price_block_cents,
104	+      });
105	+    }
106	+  }
107	+
108	+  const { error } = await supabase
109	+    .from("bookings")
110	+    .update({ status: "cancelled" })
111	+    .eq("id", bookingId);
112	+  if (error) return { ok: false, error: "Could not cancel the booking." };
113	+
114	+  revalidatePath("/account");
115	+  return { ok: true, released: release };
116	+}
117	+
118	+const rescheduleSchema = z.object({
119	+  bookingId: uuid,
120	+  scheduledAt: z.string().datetime(),
121	+});
122	+
123	+/** Move a confirmed booking to a new future time. */
124	+export async function rescheduleBooking(input: {
125	+  bookingId: string;
126	+  scheduledAt: string;
127	+}): Promise<{ ok: boolean; error?: string }> {
128	+  const profile = await requireRole("customer");
129	+  const parsed = rescheduleSchema.safeParse(input);
130	+  if (!parsed.success) return { ok: false, error: "Pick a valid time." };
131	+  if (new Date(parsed.data.scheduledAt).getTime() <= Date.now()) {
132	+    return { ok: false, error: "Pick a time in the future." };
133	+  }
134	+
135	+  const supabase = await createClient();
136	+  const { error } = await supabase
137	+    .from("bookings")
138	+    .update({
139	+      scheduled_at: parsed.data.scheduledAt,
140	+      start_mode: "scheduled",
141	+    })
142	+    .eq("id", parsed.data.bookingId)
143	+    .eq("customer_id", profile.id)
144	+    .eq("status", "confirmed");
145	+  if (error) return { ok: false, error: "Could not reschedule." };
146	+
147	+  revalidatePath("/account");
148	+  return { ok: true };
149	+}
150	+
151	+/** Update the customer's display name. */
152	+export async function updateProfileName(
153	+  name: string,
154	+): Promise<{ ok: boolean; error?: string }> {
155	+  const profile = await requireRole("customer");
156	+  const trimmed = name.trim();
157	+  if (trimmed.length < 1 || trimmed.length > 120) {
158	+    return { ok: false, error: "Enter your name." };
159	+  }
160	+  const supabase = await createClient();
161	+  const { error } = await supabase
162	+    .from("profiles")
163	+    .update({ full_name: trimmed })
164	+    .eq("id", profile.id);
165	+  if (error) return { ok: false, error: "Could not save your name." };
166	+  revalidatePath("/account/settings");
167	+  return { ok: true };
168	+}
