428	+import { type NextRequest } from "next/server";
429	+import { getUser } from "@/lib/auth";
430	+import { createClient } from "@/lib/supabase/server";
431	+import {
432	+  getBooking,
433	+  getSessionByBooking,
434	+  getApprovedProvider,
435	+} from "@/lib/db/queries";
436	+import { formatCents } from "@/lib/format";
437	+import { durationLabel } from "@/lib/time";
438	+import { t } from "@/lib/i18n";
439	+
440	+/**
441	+ * Downloadable plain-text receipt for a completed booking. Returns an
442	+ * attachment; the booking must belong to the caller (RLS-enforced read).
443	+ */
444	+export async function GET(
445	+  _req: NextRequest,
446	+  ctx: { params: Promise<{ bookingId: string }> },
447	+) {
448	+  const user = await getUser();
449	+  if (!user) {
450	+    return new Response(t("receipt.notFound"), { status: 401 });
451	+  }
452	+  const { bookingId } = await ctx.params;
453	+  const [booking, session] = await Promise.all([
454	+    getBooking(bookingId),
455	+    getSessionByBooking(bookingId),
456	+  ]);
457	+  if (!booking || booking.customer_id !== user.id || !session) {
458	+    return new Response(t("receipt.notFound"), { status: 404 });
459	+  }
460	+
461	+  const provider = await getApprovedProvider(booking.provider_id);
462	+  const supabase = await createClient();
463	+  const { data: payment } = await supabase
464	+    .from("payments")
465	+    .select("payment_ref, status")
466	+    .eq("booking_id", bookingId)
467	+    .maybeSingle();
468	+
469	+  const lines = [
470	+    t("receipt.heading"),
471	+    "",
472	+    `${t("receipt.booking")}: ${booking.id}`,
473	+    `${t("receipt.listener")}: ${provider?.display_name ?? "—"}`,
474	+    `${t("receipt.date")}: ${session.ended_at ?? "—"}`,
475	+    `${t("receipt.duration")}: ${durationLabel(session.elapsed_seconds)}`,
476	+    `${t("receipt.block")}: ${t("receipt.minutes", { minutes: session.block_minutes })}`,
477	+    session.overage_minutes > 0
478	+      ? `${t("receipt.overage")}: ${t("receipt.minutes", { minutes: session.overage_minutes })}`
479	+      : null,
480	+    `${t("receipt.total")}: ${formatCents(session.total_price_cents)}`,
481	+    `${t("receipt.payment")}: ${payment?.payment_ref ?? "—"} (${payment?.status ?? "—"})`,
482	+    "",
483	+    t("receipt.footer"),
484	+    "",
485	+  ]
486	+    .filter((l) => l !== null)
487	+    .join("\n");
488	+
489	+  return new Response(lines, {
490	+    status: 200,
491	+    headers: {
492	+      "Content-Type": "text/plain; charset=utf-8",
493	+      "Content-Disposition": `attachment; filename="heard-receipt-${booking.id.slice(0, 8)}.txt"`,
494	+    },
495	+  });
496	+}
