687	@@ -0,0 +1,67 @@
688	+"use client";
689	+
690	+import * as React from "react";
691	+import { useTransition } from "react";
692	+import { Heart } from "lucide-react";
693	+import { addFavorite, removeFavorite } from "@/app/(customer)/account/actions";
694	+import { t } from "@/lib/i18n";
695	+import { useToast } from "@/components/ui/Toast";
696	+
697	+/**
698	+ * Heart toggle to save/remove a listener. Keyboard-operable, state via
699	+ * aria-pressed (text label in aria-label, never colour alone), announced.
700	+ */
701	+export function FavoriteButton({
702	+  providerId,
703	+  providerName,
704	+  initialFavorite,
705	+}: {
706	+  providerId: string;
707	+  providerName: string;
708	+  initialFavorite: boolean;
709	+}) {
710	+  const [favorite, setFavorite] = React.useState(initialFavorite);
711	+  const [pending, startTransition] = useTransition();
712	+  const { announce } = useToast();
713	+
714	+  function toggle() {
715	+    const next = !favorite;
716	+    setFavorite(next);
717	+    startTransition(async () => {
718	+      const res = next
719	+        ? await addFavorite(providerId)
720	+        : await removeFavorite(providerId);
721	+      if (!res.ok) {
722	+        setFavorite(!next); // revert
723	+        return;
724	+      }
725	+      announce(
726	+        next
727	+          ? t("favorite.added", { name: providerName })
728	+          : t("favorite.removed", { name: providerName }),
729	+      );
730	+    });
731	+  }
732	+
733	+  return (
734	+    <button
735	+      type="button"
736	+      onClick={toggle}
737	+      disabled={pending}
738	+      aria-pressed={favorite}
739	+      aria-label={
740	+        favorite
741	+          ? t("favorite.remove", { name: providerName })
742	+          : t("favorite.add", { name: providerName })
743	+      }
744	+      className="inline-flex size-11 items-center justify-center rounded-pill border border-border-strong bg-surface text-ink-soft hover:bg-primary-tint/50 aria-pressed:border-accent aria-pressed:text-accent"
745	+    >
746	+      <Heart
747	+        size={20}
748	+        strokeWidth={2}
749	+        aria-hidden="true"
750	+        className={favorite ? "fill-accent" : ""}
751	+      />
752	+    </button>
753	+  );
754	+}
