import { type SupabaseClient } from "@supabase/supabase-js";
import { type Database } from "@/lib/supabase/types";
import { type PaymentsProvider } from "./interface";

/**
 * Mock payments: an in-DB ledger (payments / payouts) with synthetic refs. No
 * money moves. Takes the Supabase client as a dependency (injected by index.ts
 * as the service-role admin client) so the adapter stays unit-testable without
 * pulling in server-only modules.
 */

type Db = SupabaseClient<Database>;

/** Opaque, non-guessable mock reference id. */
function shortId(): string {
  return globalThis.crypto.randomUUID().replace(/-/g, "").slice(0, 16);
}

export const mockRef = {
  customer: (userId: string) => `mock_cus_${userId}`,
  account: (providerId: string) => `mock_acct_${providerId}`,
  payment: () => `mock_pay_${shortId()}`,
};

/** Recover the customer id encoded in a mock customer reference. */
export function customerIdFromRef(customerRef: string): string {
  return customerRef.startsWith("mock_cus_")
    ? customerRef.slice("mock_cus_".length)
    : customerRef;
}

export interface EarningRow {
  provider_id: string;
  provider_earnings_cents: number;
}
export interface TipRow {
  provider_id: string;
  tip_cents: number;
}

/**
 * Pure payout aggregation: sum session earnings + review tips per provider.
 * Returns providers with a positive total, sorted by id for determinism.
 */
export function aggregateEarnings(
  sessions: EarningRow[],
  tips: TipRow[],
): Array<{ providerId: string; amountCents: number }> {
  const totals = new Map<string, number>();
  for (const s of sessions) {
    totals.set(
      s.provider_id,
      (totals.get(s.provider_id) ?? 0) + s.provider_earnings_cents,
    );
  }
  for (const t of tips) {
    totals.set(t.provider_id, (totals.get(t.provider_id) ?? 0) + t.tip_cents);
  }
  return [...totals.entries()]
    .filter(([, amount]) => amount > 0)

/**
 * Payments boundary (maps to Stripe Connect later). Feature code reaches this
 * only through getPayments() in ./index — never imports mock.ts / real.ts
 * directly, and never calls Stripe outside real.ts (CLAUDE.md rule 2).
 */
export interface PaymentsProvider {
  /** Ensure a customer record exists; returns an opaque reference. */
  ensureCustomer(userId: string): Promise<{ customerRef: string }>;

  /** Authorise (hold) the block price at booking time. */
  authorizeHold(p: {
    bookingId: string;
    amountCents: number;
    customerRef: string;
  }): Promise<{ paymentRef: string; status: "authorized" }>;

  /** Capture a previously authorised hold (at session end). */
  capture(p: {
    paymentRef: string;
    amountCents: number;
  }): Promise<{ status: "captured" }>;

  /** Refund (or release) a hold. */
  refund(p: {
    paymentRef: string;
    amountCents: number;
  }): Promise<{ status: "refunded" }>;

  /** Ensure the provider has a connected payout account; returns a reference. */
  ensureConnectedAccount(providerId: string): Promise<{ accountRef: string }>;

  /** Record an earned amount for a provider from a completed session. */
  recordProviderEarning(p: {
    providerId: string;
    amountCents: number;
    sessionId: string;
  }): Promise<void>;

  /** Aggregate the week's earnings into payout rows. */
  runWeeklyPayouts(p?: {
    periodStart: string;
    periodEnd: string;
  }): Promise<{ payouts: Array<{ providerId: string; amountCents: number }> }>;
}

